<?php
declare(strict_types=1);
function deviceProfileCases(array &$tests,ControlCenter\Application $app,array $owner,array $alpha,array $beta,array $tenantA,array $tenantB,HttpFixture $http):void {
    $profile=function(array $extra=[])use($app,$alpha):array {return $app->deviceProfiles->save($alpha,null,array_replace(['name'=>'TEST device setup','prebuffer_seconds'=>'2'],$extra));};
    $fixture=function()use($app,$owner,$alpha,$tenantA):array {$c=$app->management->createCustomer($alpha,['tenant_id'=>$tenantA['id'],'name'=>'TEST device recipe']);$d=$app->management->createDevice($alpha,['customer_id'=>$c['id'],'label'=>'TEST recipe device']);$token=$app->commands->issueTestCredential($owner,$d['id']);$app->commands->checkIn($token,['capabilities'=>ControlCenter\Commands::KINDS],'127.0.0.87');return [$d,$token];};
    $snapshot=static fn(string $buffer='0')=>['schema_version'=>'1','profile_ref'=>str_repeat('a',64),'settings_revision'=>str_repeat('b',64),'live_buffer_revision'=>str_repeat('c',64),'live_prebuffer_seconds'=>$buffer,'sort_order'=>'provider','playlist_count'=>'1','enabled_playlist_count'=>'1','portal_count'=>'0','favourite_channel_count'=>'2','favourite_group_count'=>'1'];
    $tests['device recipes pin scoped templates and edits never silently change a default'] = function()use($app,$alpha,$beta,$tenantA,$tenantB,$profile):void {
        $layout=$app->layouts->create($alpha,['name'=>'TEST recipe layout','entries'=>[['name'=>'News','hidden'=>false]]]);
        $p=$profile(['layout_template_id'=>$layout['id'],'layout_version'=>1]);$recipe=$app->deviceProfiles->get($alpha,$p['id']);same(1,$recipe['definition']['layout']['version']);
        $revision=(int)($app->deviceProfiles->policy($alpha,$tenantA['id'])['policy']['revision']??0);$app->deviceProfiles->setPolicy($alpha,['profile_id'=>$p['id'],'profile_version'=>1,'enabled'=>true,'expected_revision'=>$revision]);
        $app->layouts->change($alpha,$layout['id'],['expected_version'=>1,'entries'=>[['name'=>'Sports','hidden'=>true]]]);same('News',$app->deviceProfiles->get($alpha,$p['id'])['definition']['layout']['entries'][0]['name']);
        $app->deviceProfiles->save($alpha,$p['id'],['name'=>'TEST changed recipe','expected_version'=>1,'prebuffer_seconds'=>'5']);same(1,(int)$app->deviceProfiles->policy($alpha,$tenantA['id'])['policy']['profile_version']);
        problem(404,fn()=> $app->deviceProfiles->get($beta,$p['id']));problem(404,fn()=> $app->deviceProfiles->listing($beta,['tenant_id'=>$tenantA['id']]));problem(404,fn()=> $app->deviceProfiles->jobs($beta,['tenant_id'=>$tenantA['id']]));
        problem(422,fn()=> $profile(['update_url'=>'https://forbidden.test']));problem(422,fn()=> $profile(['prebuffer_seconds'=>'999']));
        $app->deviceProfiles->setPolicy($alpha,['profile_id'=>$p['id'],'profile_version'=>1,'enabled'=>false,'expected_revision'=>$revision+1]);
        $app->deviceProfiles->setPolicy($alpha,['profile_id'=>$p['id'],'profile_version'=>1,'enabled'=>true,'expected_revision'=>$revision+2]);same(1,(int)$app->deviceProfiles->policy($alpha,$tenantA['id'])['policy']['profile_version']);$app->deviceProfiles->setPolicy($alpha,['profile_id'=>$p['id'],'profile_version'=>1,'enabled'=>false,'expected_revision'=>$revision+3]);
    };
    $tests['existing inventory is unchanged until explicitly selected and every recipe stage needs a real receipt'] = function()use($app,$alpha,$beta,$profile,$fixture,$snapshot):void {
        [$d,$token]=$fixture();$p=$profile();same(0,$app->deviceProfiles->jobs($alpha,['device_id'=>$d['id']])['total']);
        problem(422,fn()=> $app->deviceProfiles->applyExisting($alpha,$d['id'],['profile_id'=>$p['id'],'profile_version'=>1,'confirmed'=>false],ControlCenter\Database::id()));
        $key=ControlCenter\Database::id();$job=$app->deviceProfiles->applyExisting($alpha,$d['id'],['profile_id'=>$p['id'],'profile_version'=>1,'confirmed'=>true],$key);same($job,$app->deviceProfiles->applyExisting($alpha,$d['id'],['profile_id'=>$p['id'],'profile_version'=>1,'confirmed'=>true],$key));
        $app->deviceProfiles->tickDevice($d['id']);$read=$app->commands->checkIn($token,['capabilities'=>ControlCenter\Commands::KINDS],'127.0.0.87')['commands'][0];same('get_settings',$read['kind']);same('running',$app->deviceProfiles->detail($alpha,$key)['status']);
        $app->commands->acknowledge($token,$read['id'],['status'=>'succeeded','lease_token'=>$read['lease_token'],'snapshot'=>$snapshot()]);$app->deviceProfiles->afterCommand($d['id'],$read['id']);
        $write=$app->commands->checkIn($token,['capabilities'=>ControlCenter\Commands::KINDS],'127.0.0.87')['commands'][0];same('set_live_buffer',$write['kind']);same('2',$write['payload']->prebuffer_seconds);
        same('running',$app->deviceProfiles->detail($alpha,$key)['status']);$app->commands->acknowledge($token,$write['id'],['status'=>'succeeded','lease_token'=>$write['lease_token'],'snapshot'=>$snapshot('2')]);$app->deviceProfiles->afterCommand($d['id'],$write['id']);same('complete',$app->deviceProfiles->detail($alpha,$key)['status']);
        problem(404,fn()=> $app->deviceProfiles->detail($beta,$key));$app->deviceProfiles->tickDevice($d['id']);same([],$app->commands->checkIn($token,['capabilities'=>ControlCenter\Commands::KINDS],'127.0.0.87')['commands']);
    };
    $tests['portable default matching preserves target-only groups and refuses ambiguous or unrelated names'] = function():void {
        $row=static fn($ref,$name,$hidden=false)=>['ref'=>str_repeat($ref,64),'match_name'=>$name,'hidden'=>$hidden];$catalog=['profile_ref'=>str_repeat('a',64),'source_ref'=>str_repeat('b',64),'revision'=>str_repeat('c',64),'items'=>[$row('d','News'),$row('e','Sports'),$row('f','Extra',true)]];
        $plan=ControlCenter\DeviceProfiles::matchLayout($catalog,[['name'=>'Sports','hidden'=>false],['name'=>'Missing','hidden'=>true]]);same([str_repeat('e',64),str_repeat('d',64),str_repeat('f',64)],$plan['payload']['order']);same([str_repeat('f',64)],$plan['payload']['hidden']);same(['Missing'],$plan['missing']);
        problem(409,fn()=> ControlCenter\DeviceProfiles::matchLayout($catalog,[['name'=>'Unknown','hidden'=>true]]));problem(409,fn()=> ControlCenter\DeviceProfiles::matchLayout($catalog,[['name'=>'News','hidden'=>true],['name'=>'Sports','hidden'=>true]]));$catalog['items'][]=$row('1','Sports');problem(409,fn()=> ControlCenter\DeviceProfiles::matchLayout($catalog,[['name'=>'Sports','hidden'=>false]]));
    };
    $tests['recipe conflict does not refresh its revision and unassignment stops outstanding setup'] = function()use($app,$owner,$alpha,$profile,$fixture,$snapshot):void {
        [$d,$token]=$fixture();$p=$profile();$id=ControlCenter\Database::id();$app->deviceProfiles->applyExisting($alpha,$d['id'],['profile_id'=>$p['id'],'profile_version'=>1,'confirmed'=>true],$id);$app->deviceProfiles->tickDevice($d['id']);$read=$app->commands->checkIn($token,['capabilities'=>ControlCenter\Commands::KINDS],'127.0.0.87')['commands'][0];$app->commands->acknowledge($token,$read['id'],['status'=>'succeeded','lease_token'=>$read['lease_token'],'snapshot'=>$snapshot()]);$app->deviceProfiles->afterCommand($d['id'],$read['id']);$write=$app->commands->checkIn($token,['capabilities'=>ControlCenter\Commands::KINDS],'127.0.0.87')['commands'][0];$app->commands->acknowledge($token,$write['id'],['status'=>'failed','lease_token'=>$write['lease_token'],'summary'=>'Local revision changed']);$app->deviceProfiles->afterCommand($d['id'],$write['id']);same('needs_review',$app->deviceProfiles->detail($alpha,$id)['status']);
        problem(409,fn()=> $app->deviceProfiles->control($alpha,$id,['action'=>'resume']));same([],$app->commands->checkIn($token,['capabilities'=>ControlCenter\Commands::KINDS],'127.0.0.87')['commands']);
        [$other,$otherToken]=$fixture();$second=ControlCenter\Database::id();$app->deviceProfiles->applyExisting($alpha,$other['id'],['profile_id'=>$p['id'],'profile_version'=>1,'confirmed'=>true],$second);$app->deviceProfiles->tickDevice($other['id']);$app->management->detachReseller($owner,$other['id']);$app->deviceProfiles->tickDevice($other['id']);same('cancelled',$app->deviceProfiles->detail($owner,$second)['status']);problem(404,fn()=> $app->deviceProfiles->detail($alpha,$second));
    };
    $tests['nested command transactions roll back with their job transaction'] = function()use($app,$alpha,$fixture):void {
        [$d,$token]=$fixture();$before=(int)$app->db->query('SELECT COUNT(*) FROM commands WHERE device_id=?',[$d['id']])->fetchColumn();try{$app->db->transaction(function()use($app,$alpha,$d):void {$app->commands->enqueue($alpha,$d['id'],['kind'=>'get_settings'],ControlCenter\Database::id());throw new RuntimeException('TEST rollback');});}catch(RuntimeException $error){same('TEST rollback',$error->getMessage());}same($before,(int)$app->db->query('SELECT COUNT(*) FROM commands WHERE device_id=?',[$d['id']])->fetchColumn());
    };
    $tests['a pinned multi-stage recipe preserves overrides and target-only groups and requires final layout readback'] = function()use($app,$alpha,$profile,$fixture,$snapshot):void {
        [$d,$token]=$fixture();$layout=$app->layouts->create($alpha,['name'=>'TEST staged layout','entries'=>[['name'=>'Sports','hidden'=>false],['name'=>'News','hidden'=>true],['name'=>'Missing','hidden'=>true]]]);$settings=$app->preferences->save($alpha,null,['name'=>'TEST staged settings','values'=>['clock_format'=>'24h']]);$p=$profile(['layout_template_id'=>$layout['id'],'layout_version'=>1,'settings_profile_id'=>$settings['id'],'settings_version'=>1,'sort_order'=>'number']);$id=ControlCenter\Database::id();$app->deviceProfiles->applyExisting($alpha,$d['id'],['profile_id'=>$p['id'],'profile_version'=>1,'confirmed'=>true],$id);$app->deviceProfiles->tickDevice($d['id']);
        $values=[];$origins=[];foreach(ControlCenter\Preferences::RULES as $key=>$choices){$values[$key]=$choices[0];$origins[$key]='local';}$pref=['schema_version'=>1,'profile_ref'=>str_repeat('a',64),'revision'=>str_repeat('e',64),'values'=>$values,'origins'=>$origins,'base_values'=>[],'overrides'=>['auto_play_next'=>'false'],'base_preset_id'=>'','base_version'=>0];$pref['values']['auto_play_next']='false';$pref['origins']['auto_play_next']='device_profile_override';
        $catalog=['schema_version'=>1,'profile_ref'=>str_repeat('a',64),'source_ref'=>str_repeat('b',64),'revision'=>str_repeat('c',64),'page'=>1,'pages'=>1,'page_size'=>2000,'total'=>3,'order_editable'=>true,'provider_order'=>true,'sources'=>[['ref'=>str_repeat('b',64),'label'=>'Playlist 1','total'=>3]],'items'=>[]];foreach(['News','Sports','Extra'] as $i=>$name)$catalog['items'][]=['ref'=>str_repeat(dechex(10+$i),64),'label'=>$name,'match_name'=>$name,'channels'=>10,'hidden'=>$name!=='News','position'=>$i+1,'provider_position'=>$i+1];
        $plan=null;$sort='provider';$buffer='0';$seen=[];
        for($step=0;$step<10;$step++){
            $commands=$app->commands->checkIn($token,['capabilities'=>ControlCenter\Commands::KINDS],'127.0.0.87')['commands'];if(!$commands)break;$c=$commands[0];$seen[]=$c['kind'];$ack=['status'=>'succeeded','lease_token'=>$c['lease_token']];
            if($c['kind']==='get_settings')$ack['snapshot']=$snapshot();
            elseif(in_array($c['kind'],['get_preferences','apply_preferences'],true)){
                if($c['kind']==='apply_preferences'){$ctx=$app->preferences->context($token,['command_id'=>$c['id'],'lease_token'=>$c['lease_token']]);$target=$ctx['target'];$pref['base_values']=(array)$target['base_values'];$pref['overrides']=(array)$target['overrides'];$pref['base_preset_id']=$target['base_preset_id'];$pref['base_version']=$target['base_version'];foreach(array_replace($pref['base_values'],$pref['overrides']) as $key=>$value){$pref['values'][$key]=$value;$pref['origins'][$key]=isset($pref['overrides'][$key])?'device_profile_override':'base_preset';}same('false',$pref['overrides']['auto_play_next']);}
                $app->preferences->capture($token,['command_id'=>$c['id'],'lease_token'=>$c['lease_token'],'document'=>$pref]);
            }elseif($c['kind']==='get_category_layout'){$ack['catalog']=$catalog;}
            elseif($c['kind']==='set_settings'){$sort='number';$ack['snapshot']=array_replace($snapshot($buffer),['sort_order'=>$sort]);}
            elseif($c['kind']==='set_live_buffer'){$buffer='2';$ack['snapshot']=array_replace($snapshot($buffer),['sort_order'=>$sort]);}
            elseif($c['kind']==='apply_category_layout'){
                $plan=(array)$c['payload'];same([str_repeat('b',64),str_repeat('a',64),str_repeat('c',64)],$plan['order']);$byRef=array_column($catalog['items'],null,'ref');$catalog['items']=[];foreach($plan['order'] as $i=>$ref)$catalog['items'][]=array_replace($byRef[$ref],['position'=>$i+1,'hidden'=>in_array($ref,$plan['hidden'],true)]);$catalog['provider_order']=false;$catalog['revision']=str_repeat('d',64);same('running',$app->deviceProfiles->detail($alpha,$id)['status']);
            }else throw new RuntimeException('Unexpected setup operation');
            $app->commands->acknowledge($token,$c['id'],$ack);$app->deviceProfiles->afterCommand($d['id'],$c['id']);
        }
        $job=$app->deviceProfiles->detail($alpha,$id);same('complete_with_notes',$job['status']);same(['Missing'],$job['notes']);same(8,count($job['results']));same('get_category_layout',$seen[array_key_last($seen)]);check($catalog['items'][2]['hidden']);
    };
    $tests['device-profile HTTP policy and action tracking require CSRF and tenant authorization'] = function()use($app,$alpha,$beta,$profile,$fixture,$http):void {
        $csrf=$http->request('GET','/api/me',null,[],'settings-alpha')['body']['csrf'];same(403,$http->request('POST','/api/device-profiles',['name'=>'TEST denied','prebuffer_seconds'=>'2'],[],'settings-alpha')['status']);$saved=$http->request('POST','/api/device-profiles',['name'=>'TEST HTTP recipe','prebuffer_seconds'=>'2'],['X-CSRF-Token'=>$csrf],'settings-alpha');same(201,$saved['status']);same(404,$http->request('GET','/api/device-profiles/'.$saved['body']['id'],null,[],'settings-beta')['status']);
        [$d,$token]=$fixture();$c=$app->commands->enqueue($alpha,$d['id'],['kind'=>'get_settings'],ControlCenter\Database::id());same(200,$http->request('GET','/api/devices/'.$d['id'].'/commands/'.$c['id'],null,[],'settings-alpha')['status']);same(404,$http->request('GET','/api/devices/'.$d['id'].'/commands/'.$c['id'],null,[],'settings-beta')['status']);
        $p=$profile();same(403,$http->request('POST','/api/device-defaults',['profile_id'=>$p['id'],'profile_version'=>1,'enabled'=>true,'expected_revision'=>2],[],'settings-alpha')['status']);
    };
    $tests['setup maintenance expires paused work and prunes only unreferenced old recipe versions'] = function()use($app,$alpha,$profile,$fixture):void {
        [$d,$token]=$fixture();$p=$profile();$id=ControlCenter\Database::id();$app->deviceProfiles->applyExisting($alpha,$d['id'],['profile_id'=>$p['id'],'profile_version'=>1,'confirmed'=>true],$id);
        for($version=1;$version<24;$version++)$app->deviceProfiles->save($alpha,$p['id'],['name'=>'TEST retained v'.($version+1),'expected_version'=>$version,'prebuffer_seconds'=>'2']);
        $app->db->query("UPDATE device_setup_jobs SET status='paused',expires_at=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 1 SECOND) WHERE id=?",[$id]);$app->deviceProfiles->maintain();same('expired',$app->deviceProfiles->detail($alpha,$id)['status']);
        check($app->db->one('SELECT version FROM device_setup_versions WHERE profile_id=? AND version=1',[$p['id']])!==null);same(null,$app->db->one('SELECT version FROM device_setup_versions WHERE profile_id=? AND version=2',[$p['id']]));problem(409,fn()=> $app->deviceProfiles->control($alpha,$id,['action'=>'resume']));
    };
    $tests['disabling a policy cancels a concurrently advanced stage rather than a stale job snapshot'] = function()use($app,$alpha,$tenantA,$profile,$fixture):void {
        [$d,$token]=$fixture();$p=$profile();$revision=(int)($app->deviceProfiles->policy($alpha,$tenantA['id'])['policy']['revision']??0);$app->deviceProfiles->setPolicy($alpha,['profile_id'=>$p['id'],'profile_version'=>1,'enabled'=>true,'expected_revision'=>$revision]);$id=$app->db->transaction(fn()=>ControlCenter\DeviceProfiles::admit($app->db,$d['id']));check(is_string($id));
        $other=new ControlCenter\Application($app->config);$app->db->pdo->beginTransaction();
        try{$stale=$app->db->one('SELECT state FROM device_setup_jobs WHERE id=?',[$id]);same([],json_decode($stale['state'],true));$other->deviceProfiles->tickDevice($d['id']);$command=$other->db->one('SELECT id,status FROM commands WHERE device_id=? ORDER BY created_at DESC LIMIT 1',[$d['id']]);same('pending',$command['status']);
            $app->deviceProfiles->setPolicy($alpha,['profile_id'=>$p['id'],'profile_version'=>1,'enabled'=>false,'expected_revision'=>$revision+1]);$app->db->pdo->commit();
        }catch(Throwable $error){if($app->db->pdo->inTransaction())$app->db->pdo->rollBack();throw $error;}
        same('paused',$app->deviceProfiles->detail($alpha,$id)['status']);same('cancelled',$app->commands->get($alpha,$d['id'],$command['id'])['status']);
    };
}
